import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"渠道","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/index.md","filePath":"zh/integrations/channels/index.md","lastUpdated":1781609185000}'),n={name:"zh/integrations/channels/index.md"};function h(o,t,i,l,s,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="渠道" tabindex="-1">渠道 <a class="header-anchor" href="#渠道" aria-label="Permalink to &quot;渠道&quot;">​</a></h1><p>渠道把 Memoh 机器人接到消息平台。你可以在机器人 <strong>Platforms</strong> tab 里配置，让同一个机器人通过 Slack、Telegram、飞书、Discord、微信、邮件、网页端等入口被访问。</p><h2 id="支持的渠道" tabindex="-1">支持的渠道 <a class="header-anchor" href="#支持的渠道" aria-label="Permalink to &quot;支持的渠道&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>指南</th><th>备注</th></tr></thead><tbody><tr><td>Slack</td><td><a href="/zh/integrations/channels/slack.html">Slack</a></td><td>Workspace 消息、thread</td></tr><tr><td>Telegram</td><td><a href="/zh/integrations/channels/telegram.html">Telegram</a></td><td>附件、流式较好</td></tr><tr><td>飞书</td><td><a href="/zh/integrations/channels/feishu.html">飞书</a></td><td>可走 webhook 入站</td></tr><tr><td>Discord</td><td><a href="/zh/integrations/channels/discord.html">Discord</a></td><td>社群、服务器</td></tr><tr><td>QQ</td><td><a href="/zh/integrations/channels/qq.html">QQ</a></td><td>偏个人 DM</td></tr><tr><td>Matrix</td><td><a href="/zh/integrations/channels/matrix.html">Matrix</a></td><td>自建 homeserver</td></tr><tr><td>Misskey</td><td><a href="/zh/integrations/channels/misskey.html">Misskey</a></td><td>回复、反应；无流式</td></tr><tr><td>钉钉</td><td><a href="/zh/integrations/channels/dingtalk.html">钉钉</a></td><td>企业私聊/群</td></tr><tr><td>企微</td><td><a href="/zh/integrations/channels/wecom.html">企微</a></td><td>企业微信工作区</td></tr><tr><td>微信</td><td><a href="/zh/integrations/channels/weixin.html">微信</a></td><td>个人扫码登录</td></tr><tr><td>微信公众号</td><td><a href="/zh/integrations/channels/wechatoa.html">微信公众号</a></td><td>公众号 webhook</td></tr><tr><td>邮件</td><td><a href="/zh/guides/email.html">邮件</a></td><td>SMTP、Mailgun、Gmail OAuth 等邮件流程</td></tr><tr><td>Web</td><td>内置</td><td>Memoh 网页端自带</td></tr></tbody></table><h2 id="微信选项" tabindex="-1">微信选项 <a class="header-anchor" href="#微信选项" aria-label="Permalink to &quot;微信选项&quot;">​</a></h2><p>Memoh 支持两种微信相关适配：</p><ul><li><strong>微信（<code>weixin</code>）</strong>：个人号扫码登录。</li><li><strong>微信公众号（<code>wechatoa</code>）</strong>：公众号 webhook，需要 <code>App ID</code>、<code>App Secret</code>、<code>Token</code>，可选 AES 设置。</li></ul><p>按实际部署模型选择，不要混用。</p><h2 id="通用配置流程" tabindex="-1">通用配置流程 <a class="header-anchor" href="#通用配置流程" aria-label="Permalink to &quot;通用配置流程&quot;">​</a></h2><ol><li>在目标平台注册应用或机器人。</li><li>获取 API token、App ID、app secret、access token 等凭据。</li><li>在 Memoh 的机器人 <strong>Platforms</strong> tab 里添加渠道。</li><li>保存并启用渠道。</li></ol><p>不同平台的最后一步可能不同：有的要把 webhook 回调 URL 粘到平台控制台，有的要手机扫码，有的需要由 Memoh 持续维护 stream 或 WebSocket 连接。</p>',11)])])}const p=e(n,[["render",h]]);export{g as __pageData,p as default};
